fn numpy_flip(m: Vec<f32>) -> Vec<f32> {
    // Consuming the input Vec and using its into_iter() which is a
    // double-ended iterator, we can simply reverse it and collect
    // into a new Vec.
    m.into_iter().rev().collect()
}

